insert into public.topics (id, parent_id, name, weight, sort_order, key_concepts, curriculum_id)
select v.id, v.parent_id, v.name, v.weight, v.sort_order, v.key_concepts, '0153f4d4-9f3d-4abe-8de0-34a72486ae55'::uuid
from (values
    ('f282b92a-7caa-40c0-8f39-1e3f53dd1937'::uuid, '17ab22a0-fd45-47f6-866f-f7c915447a25'::uuid, 'Light travels in straight lines', 1.00, 1, array['In a uniform medium light travels in straight lines, which is why we draw rays and why opaque objects cast sharp shadows.']::text[]),
    ('504c692f-5972-4d9c-8f28-bb0c1184c8cb'::uuid, '17ab22a0-fd45-47f6-866f-f7c915447a25'::uuid, 'Laws of reflection', 1.00, 2, array['The angle of incidence equals the angle of reflection, both measured from the normal, and the incident ray, normal and reflected ray lie in one plane.']::text[]),
    ('b581c823-3822-427b-844e-9e318010913a'::uuid, '17ab22a0-fd45-47f6-866f-f7c915447a25'::uuid, 'Images in a plane mirror', 1.00, 3, array['A plane mirror forms a virtual, erect, laterally inverted image of the same size, as far behind the mirror as the object is in front.']::text[]),
    ('03a8469a-8ed3-4646-8ed1-07974de835e4'::uuid, '17ab22a0-fd45-47f6-866f-f7c915447a25'::uuid, 'Spherical mirror terms', 1.00, 4, array['Spherical mirrors are described by pole, centre of curvature, principal axis and principal focus, with focal length half the radius of curvature (f = R/2).']::text[]),
    ('cc7b6a20-f016-4abd-8793-ce6560fe576f'::uuid, '17ab22a0-fd45-47f6-866f-f7c915447a25'::uuid, 'Image formation by spherical mirrors', 1.00, 5, array['The position, nature and size of the image formed by a concave or convex mirror depend on where the object is placed relative to F and C.']::text[]),
    ('0d28ac15-1636-4727-8901-013ea7eca2b0'::uuid, '17ab22a0-fd45-47f6-866f-f7c915447a25'::uuid, 'Mirror formula and magnification', 1.00, 6, array['The mirror formula 1/v + 1/u = 1/f and magnification m = −v/u = h′/h, used with the New Cartesian sign convention, locate the image and give its size.']::text[]),
    ('ac6ce59d-842b-4dde-8468-a50d4270239f'::uuid, '17ab22a0-fd45-47f6-866f-f7c915447a25'::uuid, 'Refraction of light', 1.00, 7, array['Light bends when it passes obliquely between transparent media because its speed changes, bending towards the normal on entering an optically denser medium.']::text[]),
    ('d7f4b395-3afc-46df-8d27-4b896d31fb5c'::uuid, '17ab22a0-fd45-47f6-866f-f7c915447a25'::uuid, 'Refractive index', 1.00, 8, array['Refractive index n = c/v compares the speed of light in vacuum with its speed in a medium; higher n means optically denser, which need not mean heavier.']::text[]),
    ('29c3783e-5552-4c44-8796-a4c94e22ccd9'::uuid, '17ab22a0-fd45-47f6-866f-f7c915447a25'::uuid, 'Image formation by lenses', 1.00, 9, array['Convex lenses converge light and concave lenses diverge it, and the image a lens forms depends on where the object sits relative to F and 2F.']::text[]),
    ('cad5e4a3-e8f3-4c7c-8508-5a7e72902b4d'::uuid, '17ab22a0-fd45-47f6-866f-f7c915447a25'::uuid, 'Lens formula and power', 1.00, 10, array['The lens formula 1/v − 1/u = 1/f locates images, and power P = 1/f (f in metres) gives a lens''s strength in dioptres, positive for convex and negative for concave.']::text[]),
    ('afe6a32a-7938-4947-8c74-0b9a7d081bc7'::uuid, 'c8a3d83b-6924-4f35-8536-ce5f1922fc36'::uuid, 'The eye and accommodation', 1.00, 1, array['The eye lens forms a real, inverted image on the retina, and ciliary muscles change its curvature so a normal eye sees clearly from 25 cm to infinity.']::text[]),
    ('40f58799-31c4-4664-84ac-74439d83ee94'::uuid, 'c8a3d83b-6924-4f35-8536-ce5f1922fc36'::uuid, 'Defects of vision and correction', 1.00, 2, array['Myopia is corrected with a concave lens, hypermetropia with a convex lens, and presbyopia often with bifocal lenses.']::text[]),
    ('7638b427-80e3-4ecd-80b7-6e59c6424aee'::uuid, 'c8a3d83b-6924-4f35-8536-ce5f1922fc36'::uuid, 'Prism and dispersion', 1.00, 3, array['A glass prism splits white light into the VIBGYOR spectrum because each colour bends by a different amount, violet the most and red the least.']::text[]),
    ('44cc0740-f648-4583-85fd-596d44e6fa40'::uuid, 'c8a3d83b-6924-4f35-8536-ce5f1922fc36'::uuid, 'Atmospheric refraction', 1.00, 4, array['Refraction by air layers of changing refractive index makes stars twinkle and the Sun visible about 2 minutes before actual sunrise and after actual sunset.']::text[]),
    ('f0de0ca5-1732-49bc-8815-d3e45b562352'::uuid, 'c8a3d83b-6924-4f35-8536-ce5f1922fc36'::uuid, 'Scattering of light', 1.00, 5, array['Tiny particles scatter shorter (blue) wavelengths more than longer (red) ones, explaining the blue sky, red sunrises and sunsets, and the Tyndall effect.']::text[]),
    ('fa0bb3bc-16ac-4fbe-8a89-03c04066abd2'::uuid, '759c10ff-68b8-48fc-80b6-8adb76acab68'::uuid, 'Electric charge and current', 1.00, 1, array['Electric current is the rate of flow of charge (I = Q/t); conventional current flows from + to − while electrons drift the other way, and current is not used up.']::text[]),
    ('1c2b9f29-b68a-49fa-823a-825cb7ef77bd'::uuid, '759c10ff-68b8-48fc-80b6-8adb76acab68'::uuid, 'Potential difference', 1.00, 2, array['Potential difference V = W/Q is the work done per unit charge between two points, measured in volts with a voltmeter connected in parallel.']::text[]),
    ('dd3df846-b4b5-4a1e-8fdb-45cf621d27dc'::uuid, '759c10ff-68b8-48fc-80b6-8adb76acab68'::uuid, 'Ohm''s law', 1.00, 3, array['At constant temperature the current through a metallic conductor is proportional to the potential difference across it (V = IR), so resistance is a property of the conductor.']::text[]),
    ('a5a93904-9679-4f33-8c4c-4bdc46a19bc0'::uuid, '759c10ff-68b8-48fc-80b6-8adb76acab68'::uuid, 'Factors affecting resistance', 1.00, 4, array['Resistance R = ρl/A grows with length and falls with cross-sectional area, while resistivity ρ depends only on the material and temperature.']::text[]),
    ('3bb42e56-9e47-449b-8878-b44affcdf81c'::uuid, '759c10ff-68b8-48fc-80b6-8adb76acab68'::uuid, 'Resistors in series', 1.00, 5, array['In series the same current flows through every component, potential differences add up, and Rs = R1 + R2 + R3.']::text[]),
    ('2b9c8a71-8371-4ef1-8998-4d12854108ee'::uuid, '759c10ff-68b8-48fc-80b6-8adb76acab68'::uuid, 'Resistors in parallel', 1.00, 6, array['In parallel each branch gets the full potential difference, branch currents add up, and 1/Rp = 1/R1 + 1/R2 + … is less than the smallest resistance.']::text[]),
    ('05e5c4b8-4b57-4122-8efb-4ae6560fa624'::uuid, '759c10ff-68b8-48fc-80b6-8adb76acab68'::uuid, 'Heating effect of current', 1.00, 7, array['Joule''s law H = I²Rt says heat grows with the square of the current, which is used in heaters, bulbs and fuses.']::text[]),
    ('0b6bb3a5-577d-426f-8e4b-a3a09dd05b59'::uuid, '759c10ff-68b8-48fc-80b6-8adb76acab68'::uuid, 'Electric power and energy', 1.00, 8, array['Electric power P = VI = I²R = V²/R is the rate of using electrical energy, and the commercial unit of energy is the kilowatt-hour (1 kWh = 3.6 × 10⁶ J).']::text[]),
    ('3b10b271-dca9-4fb8-89e7-3fb9e60c532a'::uuid, '19a56875-4578-4938-867e-ff06b1d8977b'::uuid, 'Magnetic field lines', 1.00, 1, array['Outside a magnet field lines run from north to south, never intersect, and crowd together where the field is stronger.']::text[]),
    ('180afbe2-8f1d-4624-891d-95c3cebe2d52'::uuid, '19a56875-4578-4938-867e-ff06b1d8977b'::uuid, 'Field due to a straight current', 1.00, 2, array['A straight current-carrying wire produces concentric circular field lines whose direction follows the right-hand thumb rule and whose strength rises with current.']::text[]),
    ('9246dada-ee7e-4102-802c-eaa5c07ddae3'::uuid, '19a56875-4578-4938-867e-ff06b1d8977b'::uuid, 'Solenoid and electromagnet', 1.00, 3, array['A current-carrying solenoid has a nearly uniform field inside and acts like a bar magnet; with a soft-iron core it becomes an electromagnet.']::text[]),
    ('3bb5b5c9-4627-4a6c-8c93-93ec363a13e1'::uuid, '19a56875-4578-4938-867e-ff06b1d8977b'::uuid, 'Force on a current in a field', 1.00, 4, array['A current-carrying conductor in a magnetic field feels a force, largest when current is perpendicular to the field, with direction given by Fleming''s left-hand rule.']::text[]),
    ('0f4d2cae-cf64-4062-8b65-f1dffd3bb2d3'::uuid, '19a56875-4578-4938-867e-ff06b1d8977b'::uuid, 'Domestic electric circuits', 1.00, 5, array['Homes use live, neutral and earth wires with appliances in parallel, protected by a fuse or MCB in the live wire against overloading and short circuits.']::text[])
) as v(id, parent_id, name, weight, sort_order, key_concepts)
on conflict do nothing;

