insert into public.questions
    (id, topic_id, question_type, body, options, correct_answer, explanation, difficulty, marks,
     is_ai_generated, is_verified, option_misconceptions)
values
    ('c62151ab-4ce4-430b-83c5-96bb3a4055f1'::uuid, 'f282b92a-7caa-40c0-8f39-1e3f53dd1937'::uuid, 'mcq', 'Why does an opaque ball cast a sharp shadow in sunlight?', array['Light curves around the ball, so only a small area stays dark', 'Light travels in straight lines and cannot pass through the ball', 'Our eyes send fewer rays into the region behind the ball', 'The ball gives out darkness']::text[], '[1]'::jsonb, 'Light travels in straight lines in a uniform medium, so the region behind an opaque object receives no light.', 'easy', 1, false, true, array['Light curves around opaque objects', '', 'We see because eyes send out light', '']::text[]),
    ('3d7bc7a8-57f3-4937-817c-aa972998d375'::uuid, 'f282b92a-7caa-40c0-8f39-1e3f53dd1937'::uuid, 'mcq', 'You read a book in a room lit by a lamp. Which path does light take so that you can see the page?', array['From your eye to the page and back to your eye', 'From your eye to the lamp, then to the page', 'From the page straight to the lamp', 'From the lamp to the page, then from the page into your eye']::text[], '[3]'::jsonb, 'We see an object when light from a source is reflected by the object into our eyes; eyes receive light, they do not send it out.', 'medium', 1, false, true, array['We see because eyes send out light', 'We see because eyes send out light', '', '']::text[]),
    ('063cbf2c-ec6d-4cca-839d-81bd240b456f'::uuid, 'f282b92a-7caa-40c0-8f39-1e3f53dd1937'::uuid, 'mcq', 'In a pinhole camera, the image of a candle flame on the screen is inverted. Why?', array['Rays from the top of the flame travel in straight lines through the hole and land at the bottom of the screen', 'The pinhole acts like a lens that flips the image', 'Light bends around the edges of the hole and turns over', 'The screen sends rays back through the hole, which cross over']::text[], '[0]'::jsonb, 'Straight-line rays from the top and bottom of the flame cross at the pinhole, so the top of the object maps to the bottom of the image.', 'hard', 1, false, true, array['', '', 'Light curves around opaque objects', 'We see because eyes send out light']::text[]),
    ('3c5eeb9a-a95e-42bb-8f0a-132371d6e2af'::uuid, '504c692f-5972-4d9c-8f28-bb0c1184c8cb'::uuid, 'mcq', 'A ray strikes a plane mirror making an angle of 30° with the mirror surface. What is the angle of reflection?', array['30°', '90°', '60°', '15°']::text[], '[2]'::jsonb, 'Angles are measured from the normal: the angle of incidence is 90° − 30° = 60°, so the angle of reflection is also 60°.', 'easy', 1, false, true, array['Measures angles from the mirror surface', '', '', '']::text[]),
    ('dd5c1682-0093-477a-8bd8-ed8cafd851a7'::uuid, '504c692f-5972-4d9c-8f28-bb0c1184c8cb'::uuid, 'mcq', 'You can see a sheet of paper from any direction, but you cannot see your face in it. Why?', array['Paper''s rough surface reflects light in many directions, and each ray still obeys the laws of reflection', 'Paper does not reflect light at all; it glows faintly', 'The laws of reflection do not apply to rough surfaces', 'Paper absorbs all the light that falls on it']::text[], '[0]'::jsonb, 'Paper gives diffuse reflection: its tiny surface bumps face many directions, so reflected rays scatter, though each one obeys the laws of reflection.', 'medium', 1, false, true, array['', 'Only shiny surfaces reflect light', 'Only shiny surfaces reflect light', '']::text[]),
    ('5e8571a5-2351-4fe0-8091-c30478579d1b'::uuid, '504c692f-5972-4d9c-8f28-bb0c1184c8cb'::uuid, 'mcq', 'Two plane mirrors are placed at 90° to each other. A ray hits the first mirror with an angle of incidence of 40°. What is the angle of incidence at the second mirror?', array['90°', '40°', '130°', '50°']::text[], '[3]'::jsonb, 'The reflected ray makes 50° with the first mirror, so it meets the perpendicular mirror at 40° to its surface, giving an angle of incidence of 90° − 40° = 50°.', 'hard', 1, false, true, array['', 'Measures angles from the mirror surface', '', '']::text[]),
    ('f6eedc74-f4d2-42a3-82ff-f980229ee5bf'::uuid, 'b581c823-3822-427b-844e-9e318010913a'::uuid, 'mcq', 'You stand 2 m in front of a plane mirror. How far is your image from you?', array['2 m', '4 m', '1 m', '0 m, it is on the mirror']::text[], '[1]'::jsonb, 'The image is 2 m behind the mirror, so it is 2 m + 2 m = 4 m from you.', 'easy', 1, false, true, array['Image forms on the mirror surface', '', '', 'Image forms on the mirror surface']::text[]),
    ('86a8521f-3073-45e5-89bf-0d0d84d2f58a'::uuid, 'b581c823-3822-427b-844e-9e318010913a'::uuid, 'mcq', 'A boy walks away from a large plane mirror. What happens to the actual size of his image?', array['It decreases', 'It increases', 'It stays the same', 'It becomes zero beyond a few metres']::text[], '[2]'::jsonb, 'A plane mirror always forms an image the same size as the object; it only looks smaller from farther away because it is more distant.', 'medium', 1, false, true, array['Image gets smaller as you move away', '', '', 'Image gets smaller as you move away']::text[]),
    ('c5e4ee4c-895f-4efa-8fc5-a33cf85a685a'::uuid, 'b581c823-3822-427b-844e-9e318010913a'::uuid, 'mcq', 'A girl stands 3 m from a plane mirror and then walks 1 m towards it. By how much does the distance between her and her image decrease?', array['1 m', '2 m', '4 m', 'It does not change, because the image is real and fixed']::text[], '[1]'::jsonb, 'The distance to her image falls from 3 + 3 = 6 m to 2 + 2 = 4 m, a decrease of 2 m, because the image moves with her.', 'hard', 1, false, true, array['Image forms on the mirror surface', '', '', 'Plane mirror image can form on a screen']::text[]),
    ('de054d88-7c0a-4f0b-88dd-1526ae8bf1b4'::uuid, '03a8469a-8ed3-4646-8ed1-07974de835e4'::uuid, 'mcq', 'A concave mirror has a radius of curvature of 30 cm. What is its focal length?', array['60 cm', '30 cm', '15 cm', '7.5 cm']::text[], '[2]'::jsonb, 'For a spherical mirror f = R/2, so f = 30/2 = 15 cm.', 'easy', 1, false, true, array['Focal length equals radius of curvature', 'Focal length equals radius of curvature', '', '']::text[]),
    ('e050b0d8-cb71-41cf-8059-c1c1a8feefce'::uuid, '03a8469a-8ed3-4646-8ed1-07974de835e4'::uuid, 'mcq', 'Rays parallel to the principal axis fall on a convex mirror. After reflection they', array['meet at the focus in front of the mirror', 'appear to diverge from the focus behind the mirror', 'meet at the centre of curvature', 'retrace their path']::text[], '[1]'::jsonb, 'A convex mirror diverges light; parallel rays reflect so that they appear to come from the principal focus behind the mirror.', 'medium', 1, false, true, array['Convex mirror has a real focus', '', 'Focal length equals radius of curvature', '']::text[]),
    ('a31d27c0-6592-4eaf-8e2d-f6b1805b7106'::uuid, '03a8469a-8ed3-4646-8ed1-07974de835e4'::uuid, 'mcq', 'The distance between the pole and the centre of curvature of a concave mirror is 24 cm. A ray passes through the centre of curvature and strikes the mirror. Where does it go after reflection?', array['Through the focus, 24 cm from the pole', 'Parallel to the principal axis', 'Through a point 48 cm from the pole', 'Back along the same path']::text[], '[3]'::jsonb, 'A ray through the centre of curvature meets the mirror along the normal, so it is reflected back along the same path.', 'hard', 1, false, true, array['Focal length equals radius of curvature', '', '', '']::text[]),
    ('03cf46c1-c050-4597-829e-9732e621b333'::uuid, 'cc7b6a20-f016-4abd-8793-ce6560fe576f'::uuid, 'mcq', 'Which mirror is used as a rear-view mirror in vehicles, and why?', array['Concave, because it magnifies the vehicles behind', 'Convex, because it gives an erect, diminished image over a wide field of view', 'Plane, because it gives a real image', 'Concave, because it always forms real images']::text[], '[1]'::jsonb, 'A convex mirror always gives an erect, diminished image and covers a wide field of view, which is ideal for seeing traffic behind.', 'easy', 1, false, true, array['Rear-view mirrors are concave', '', '', 'Concave mirrors always form real images']::text[]),
    ('0f25728e-daad-4fe2-8fe0-c906087dd055'::uuid, 'cc7b6a20-f016-4abd-8793-ce6560fe576f'::uuid, 'mcq', 'An object is placed between the pole and the focus of a concave mirror. The image is', array['real, inverted and magnified', 'real, inverted and diminished', 'virtual, erect and magnified', 'virtual, erect and diminished']::text[], '[2]'::jsonb, 'With the object between P and F, a concave mirror forms a virtual, erect, magnified image behind the mirror, as in a shaving mirror.', 'medium', 1, false, true, array['Concave mirrors always form real images', 'Concave mirrors always form real images', '', '']::text[]),
    ('9a74d848-ef98-41ce-8192-c4d9be3d441d'::uuid, 'cc7b6a20-f016-4abd-8793-ce6560fe576f'::uuid, 'mcq', 'An object is moved from very far away towards a convex mirror. Which statement about its image is correct?', array['It stays virtual and erect, and grows but always stays smaller than the object', 'It becomes real when the object crosses the focus', 'It becomes magnified when the object is very close', 'It becomes inverted near the mirror']::text[], '[0]'::jsonb, 'A convex mirror always forms a virtual, erect, diminished image; as the object approaches, the image grows towards but never exceeds the object''s size.', 'hard', 1, false, true, array['', 'Convex mirror can enlarge or form real images', 'Convex mirror can enlarge or form real images', '']::text[]),
    ('8b85080d-82ba-4b9d-8fcc-95aabf40a3a4'::uuid, '0d28ac15-1636-4727-8901-013ea7eca2b0'::uuid, 'mcq', 'In the New Cartesian sign convention, the object distance u for an object placed in front of a mirror is', array['always negative', 'always positive', 'positive for a concave mirror and negative for a convex mirror', 'zero']::text[], '[0]'::jsonb, 'The object is placed to the left, and distances measured against the direction of incident light are negative, so u is always negative.', 'easy', 1, false, true, array['', 'Takes all distances as positive', '', '']::text[]),
    ('abd1710a-33da-4b35-8f05-d7fcc60027e7'::uuid, '0d28ac15-1636-4727-8901-013ea7eca2b0'::uuid, 'mcq', 'A concave mirror produces a magnification m = −2. This means the image is', array['virtual, erect and twice the size of the object', 'real, inverted and twice the size of the object', 'real, inverted and half the size of the object', 'virtual and half the size of the object']::text[], '[1]'::jsonb, 'The minus sign means the image is real and inverted; the size |m| = 2 means it is twice as large as the object.', 'medium', 1, false, true, array['', '', 'Negative magnification means a smaller image', 'Negative magnification means a smaller image']::text[]),
    ('6fbd16c9-89e2-4be5-84b1-51d401722a0b'::uuid, '0d28ac15-1636-4727-8901-013ea7eca2b0'::uuid, 'mcq', 'An object is placed 30 cm in front of a concave mirror of focal length 15 cm. Where is the image formed?', array['30 cm behind the mirror', '10 cm in front of the mirror', '30 cm in front of the mirror', '15 cm in front of the mirror']::text[], '[2]'::jsonb, 'With u = −30 cm and f = −15 cm, 1/v = 1/f − 1/u = −1/15 + 1/30 = −1/30, so v = −30 cm: the image is 30 cm in front, at C.', 'hard', 1, false, true, array['Takes all distances as positive', 'Takes all distances as positive', '', '']::text[]),
    ('c0e4c20b-6ea5-46a7-84dd-0642a338f55b'::uuid, 'ac6ce59d-842b-4dde-8468-a50d4270239f'::uuid, 'mcq', 'A ray of light travels obliquely from air into glass. At the surface it', array['bends away from the normal', 'bends towards the normal', 'goes straight on, since its speed does not change', 'is completely reflected']::text[], '[1]'::jsonb, 'Light slows down in glass, an optically denser medium, so it bends towards the normal.', 'easy', 1, false, true, array['Bends away from normal in denser medium', '', 'Light''s speed is the same in every medium', '']::text[]),
    ('b6dfdc1f-396a-47f7-8e21-fe986fc9157a'::uuid, 'ac6ce59d-842b-4dde-8468-a50d4270239f'::uuid, 'mcq', 'A ray strikes a glass slab along the normal. Inside the slab it', array['bends towards the normal', 'bends away from the normal', 'goes straight on, but travels more slowly', 'goes straight on at the same speed']::text[], '[2]'::jsonb, 'A ray along the normal does not change direction, but it still slows down because glass is optically denser than air.', 'medium', 1, false, true, array['A ray along the normal also bends', 'A ray along the normal also bends', '', 'Light''s speed is the same in every medium']::text[]),
    ('c7d09925-65b4-40fd-853f-9663d11ca4fd'::uuid, 'ac6ce59d-842b-4dde-8468-a50d4270239f'::uuid, 'mcq', 'A pencil partly dipped in water looks bent at the water surface. What is the best explanation?', array['Water physically bends the pencil', 'Light from the immersed part bends towards the normal as it leaves water, so that part looks deeper', 'Light travels at the same speed in water, but reflects off the surface', 'Light from the immersed part bends away from the normal as it leaves water into air, so that part looks raised']::text[], '[3]'::jsonb, 'Going from water into air (denser to rarer), light bends away from the normal, so the immersed part appears raised and the pencil looks bent.', 'hard', 1, false, true, array['', 'Bends away from normal in denser medium', 'Light''s speed is the same in every medium', '']::text[]),
    ('7a38d880-3b17-4284-89e5-9520930e929b'::uuid, 'd7f4b395-3afc-46df-8d27-4b896d31fb5c'::uuid, 'mcq', 'The refractive index of diamond is 2.42. This means', array['light travels in vacuum 2.42 times faster than in diamond', 'light travels 2.42 times faster in diamond than in vacuum', 'diamond is 2.42 times heavier than glass', 'light bends by 2.42° inside diamond']::text[], '[0]'::jsonb, 'n = c/v, so n = 2.42 means the speed of light in vacuum is 2.42 times its speed in diamond.', 'easy', 1, false, true, array['', 'Higher refractive index means faster light', 'Optically denser means heavier', '']::text[]),
    ('43770002-8762-4881-8ec9-d41ad7e134dd'::uuid, 'd7f4b395-3afc-46df-8d27-4b896d31fb5c'::uuid, 'mcq', 'Kerosene (n = 1.44) has a lower mass density than water (n = 1.33). Which is optically denser?', array['Water, because it is heavier', 'Water, because light travels faster in it', 'Kerosene, because its refractive index is higher', 'Both are equally dense optically']::text[], '[2]'::jsonb, 'Optical density depends on refractive index, not mass density; kerosene has the higher n, so light is slower in it.', 'medium', 1, false, true, array['Optically denser means heavier', 'Higher refractive index means faster light', '', '']::text[]),
    ('21b51be5-6972-4255-84ba-79cee8819339'::uuid, 'd7f4b395-3afc-46df-8d27-4b896d31fb5c'::uuid, 'mcq', 'The speed of light in a medium is 2 × 10⁸ m/s. Taking c = 3 × 10⁸ m/s, what is its refractive index?', array['0.67', '1.33', '6', '1.5']::text[], '[3]'::jsonb, 'n = c/v = (3 × 10⁸)/(2 × 10⁸) = 1.5; a refractive index is never less than 1.', 'hard', 1, false, true, array['Higher refractive index means faster light', '', '', '']::text[]),
    ('578a717f-8e50-4460-8b35-39ee0c183e81'::uuid, '29c3783e-5552-4c44-8796-a4c94e22ccd9'::uuid, 'mcq', 'Half of a convex lens is covered with black paper. What happens to the image of an object?', array['It disappears', 'It shows only half of the object', 'It is complete but less bright', 'It becomes twice as large']::text[], '[2]'::jsonb, 'Every part of the lens forms the whole image, so the uncovered half still forms a complete image, only with less light.', 'easy', 1, false, true, array['', 'Covering half a lens cuts half the image', '', '']::text[]),
    ('103c1ac5-09bf-46d4-8b75-3f1aca46fc84'::uuid, '29c3783e-5552-4c44-8796-a4c94e22ccd9'::uuid, 'mcq', 'An object is placed beyond 2F₁ of a convex lens. The image is', array['real, inverted, diminished and between F₂ and 2F₂', 'virtual, erect and magnified', 'real, inverted, magnified and beyond 2F₂', 'real, inverted, same size and at 2F₂']::text[], '[0]'::jsonb, 'For an object beyond 2F₁, a convex lens forms a real, inverted, diminished image between F₂ and 2F₂.', 'medium', 1, false, true, array['', 'A convex lens always magnifies', 'A convex lens always magnifies', '']::text[]),
    ('26699fa3-d288-462a-8a1c-197bba95b416'::uuid, '29c3783e-5552-4c44-8796-a4c94e22ccd9'::uuid, 'mcq', 'A concave lens is used to view an object kept at any distance. The image is always', array['real and inverted', 'real when the object is beyond 2F', 'virtual, erect and magnified', 'virtual, erect and diminished']::text[], '[3]'::jsonb, 'A concave lens diverges light, so for any object position it forms a virtual, erect, diminished image on the same side as the object.', 'hard', 1, false, true, array['Concave lens can form real images', 'Concave lens can form real images', '', '']::text[]),
    ('1a452450-364e-43f3-8a35-9df87a8b4520'::uuid, 'cad5e4a3-e8f3-4c7c-8508-5a7e72902b4d'::uuid, 'mcq', 'A convex lens has a focal length of 25 cm. What is its power?', array['+0.04 D', '+4 D', '−4 D', '+25 D']::text[], '[1]'::jsonb, 'P = 1/f with f in metres: P = 1/0.25 m = +4 D, positive because the lens is convex.', 'easy', 1, false, true, array['Uses focal length in cm for power', '', 'Swaps the sign of lens power', 'Uses focal length in cm for power']::text[]),
    ('fac59f2d-cfcd-43b8-8063-553e8b9373ca'::uuid, 'cad5e4a3-e8f3-4c7c-8508-5a7e72902b4d'::uuid, 'mcq', 'A lens has a power of −2.5 D. It is a', array['convex lens of focal length 40 cm', 'concave lens of focal length 2.5 cm', 'concave lens of focal length 40 cm', 'convex lens of focal length 2.5 m']::text[], '[2]'::jsonb, 'f = 1/P = 1/(−2.5) m = −0.4 m = −40 cm; a negative focal length means a concave lens.', 'medium', 1, false, true, array['Swaps the sign of lens power', 'Uses focal length in cm for power', '', '']::text[]),
    ('5efffeb1-06df-449a-8736-ed800cdea0a5'::uuid, 'cad5e4a3-e8f3-4c7c-8508-5a7e72902b4d'::uuid, 'mcq', 'An object is placed 30 cm in front of a convex lens of focal length 20 cm. Where is the image?', array['12 cm on the other side of the lens', '60 cm on the same side as the object', '10 cm on the other side of the lens', '60 cm on the other side of the lens']::text[], '[3]'::jsonb, 'With u = −30 cm and f = +20 cm, 1/v = 1/f + 1/u = 1/20 − 1/30 = 1/60, so v = +60 cm: a real image on the other side.', 'hard', 1, false, true, array['Uses the mirror formula for lenses', '', '', '']::text[]),
    ('9ead298c-2fd0-4e8f-8e03-c76afcce7178'::uuid, 'afe6a32a-7938-4947-8c74-0b9a7d081bc7'::uuid, 'mcq', 'The image formed on the retina of the human eye is', array['virtual and erect', 'real and inverted', 'real and erect', 'virtual and inverted']::text[], '[1]'::jsonb, 'The eye lens is a convex lens that forms a real, inverted image on the retina; the brain interprets it as upright.', 'easy', 1, false, true, array['Image on the retina is upright', '', 'Image on the retina is upright', '']::text[]),
    ('2879a720-6d0b-471c-8b09-15a59122afbe'::uuid, 'afe6a32a-7938-4947-8c74-0b9a7d081bc7'::uuid, 'mcq', 'You shift your gaze from a distant tree to a book in your hands. How does the eye adjust?', array['The eye lens moves closer to the retina', 'The pupil gets larger to bring the book into focus', 'The eye lens becomes thinner', 'The ciliary muscles contract, so the eye lens becomes thicker']::text[], '[3]'::jsonb, 'For near objects the ciliary muscles contract, making the lens thicker and its focal length shorter; this is accommodation.', 'medium', 1, false, true, array['Eye focuses by moving the lens', 'The pupil does the focusing', '', '']::text[]),
    ('d6391095-1109-4398-8d8c-0bf3add7cc3d'::uuid, 'afe6a32a-7938-4947-8c74-0b9a7d081bc7'::uuid, 'mcq', 'Why can a normal eye not see an object held 10 cm away clearly?', array['The ciliary muscles cannot make the lens thick enough, so the image would form behind the retina', 'The pupil cannot open wide enough', 'The lens cannot move far enough forward', 'Light from near objects does not reach the retina']::text[], '[0]'::jsonb, 'The eye''s focal length cannot be reduced below a limit, so objects closer than the near point (about 25 cm) cannot be focused on the retina.', 'hard', 1, false, true, array['', 'The pupil does the focusing', 'Eye focuses by moving the lens', '']::text[]),
    ('6d01d352-1fad-4078-8620-a0c767eababd'::uuid, '40f58799-31c4-4664-84ac-74439d83ee94'::uuid, 'mcq', 'A person with myopia can see clearly', array['only nearby objects', 'only distant objects', 'neither near nor distant objects', 'objects only in bright light']::text[], '[0]'::jsonb, 'Myopia is near-sightedness: nearby objects are clear, but distant objects are blurred because their image forms in front of the retina.', 'easy', 1, false, true, array['', 'Mixes up near- and far-sightedness', '', '']::text[]),
    ('88f87cea-896e-4b12-88f6-f92d31f32705'::uuid, '40f58799-31c4-4664-84ac-74439d83ee94'::uuid, 'mcq', 'Myopia is corrected using', array['a convex lens of suitable power', 'a concave lens of suitable power', 'a bifocal lens with a convex upper part', 'no lens; only eye exercises help']::text[], '[1]'::jsonb, 'A concave (diverging) lens moves the image of distant objects back onto the retina.', 'medium', 1, false, true, array['Myopia is corrected with a convex lens', '', '', '']::text[]),
    ('c8e59f98-4f5c-4d44-8751-0653b147efe4'::uuid, '40f58799-31c4-4664-84ac-74439d83ee94'::uuid, 'mcq', 'The far point of a myopic person is 80 cm in front of the eye. What is the power of the lens needed to correct this?', array['−0.0125 D', '+1.25 D', '+0.8 D', '−1.25 D']::text[], '[3]'::jsonb, 'A concave lens of f = −80 cm = −0.8 m is needed, so P = 1/f = −1.25 D.', 'hard', 1, false, true, array['', 'Myopia is corrected with a convex lens', '', '']::text[]),
    ('8c6a881e-5dac-43a6-8c89-95f6d21fa345'::uuid, '7638b427-80e3-4ecd-80b7-6e59c6424aee'::uuid, 'mcq', 'When white light passes through a glass prism, a band of colours is seen. Why?', array['The prism adds colours to the white light', 'White light is made of colours that bend by different amounts', 'The prism reflects only coloured light', 'The glass heats up and gives out colours']::text[], '[1]'::jsonb, 'White light is a mixture of colours; each colour has a slightly different refractive index in glass, so they separate (dispersion).', 'easy', 1, false, true, array['The prism creates the colours', '', '', 'The prism creates the colours']::text[]),
    ('14cc0e3b-8f51-40ee-89d9-3d49053223ab'::uuid, '7638b427-80e3-4ecd-80b7-6e59c6424aee'::uuid, 'mcq', 'In the spectrum formed by a prism, which colour is deviated the most?', array['Red', 'Green', 'Violet', 'All colours deviate equally']::text[], '[2]'::jsonb, 'Violet has the highest refractive index in glass, so it bends the most; red bends the least.', 'medium', 1, false, true, array['Red light bends the most', '', '', '']::text[]),
    ('7601cfc4-3612-4392-81a1-6f58fb3b7335'::uuid, '7638b427-80e3-4ecd-80b7-6e59c6424aee'::uuid, 'mcq', 'A second, identical prism is placed upside down after the first prism. What comes out of the second prism?', array['An even wider spectrum', 'New colours made by the second prism', 'White light, because the colours recombine', 'Only red light, because red bends the most']::text[], '[2]'::jsonb, 'The inverted prism bends each colour back by the same amount, so the colours recombine into white light, as Newton showed.', 'hard', 1, false, true, array['', 'The prism creates the colours', '', 'Red light bends the most']::text[]),
    ('3643ebfb-16be-4667-859b-35f4648b1ec3'::uuid, '44cc0740-f648-4583-85fd-596d44e6fa40'::uuid, 'mcq', 'Stars appear to twinkle because', array['starlight is refracted by air layers whose refractive index keeps changing', 'stars give out light in pulses', 'clouds keep passing in front of them', 'air cannot bend light, so we see their true flicker']::text[], '[0]'::jsonb, 'Changing air layers keep shifting the path of starlight, so the amount of light entering the eye flickers.', 'easy', 1, false, true, array['', 'Stars twinkle because they flicker', '', 'Air cannot bend light']::text[]),
    ('5cafd5fc-1b47-4343-826b-fd378f3546e4'::uuid, '44cc0740-f648-4583-85fd-596d44e6fa40'::uuid, 'mcq', 'Planets do not twinkle like stars. Why?', array['They do twinkle, exactly as much as stars', 'Planets are much closer and act as extended sources, so the flicker averages out', 'Planets do not reflect light', 'Planets give out their own steady light']::text[], '[1]'::jsonb, 'A planet is seen as a collection of point sources; their variations cancel out on average, so it does not twinkle.', 'medium', 1, false, true, array['Planets twinkle just like stars', '', '', '']::text[]),
    ('5cbe83f9-91ce-4506-82fe-90964013a615'::uuid, '44cc0740-f648-4583-85fd-596d44e6fa40'::uuid, 'mcq', 'Because of atmospheric refraction, the Sun is visible', array['only after the actual sunrise, because light goes straight through air', 'about 2 minutes after the actual sunrise', 'about 2 minutes before the actual sunrise and after the actual sunset', 'only when the sky is cloudy']::text[], '[2]'::jsonb, 'The atmosphere bends sunlight over the horizon, so we see the Sun about 2 minutes before it actually rises and after it actually sets.', 'hard', 1, false, true, array['Air cannot bend light', '', '', '']::text[]),
    ('26e8621b-f9c4-456a-86b1-19072abc896c'::uuid, 'f0de0ca5-1732-49bc-8815-d3e45b562352'::uuid, 'mcq', 'The clear sky appears blue because', array['it reflects the colour of the oceans', 'air molecules scatter blue light more than red light', 'air molecules scatter red light more than blue light', 'the Sun gives out mostly blue light']::text[], '[1]'::jsonb, 'Air molecules are much smaller than the wavelength of visible light and scatter shorter (blue) wavelengths much more strongly.', 'easy', 1, false, true, array['Sky is blue because it reflects the sea', '', 'Red light is scattered the most', '']::text[]),
    ('109cb6d2-e4df-43a0-899c-db688b4666b2'::uuid, 'f0de0ca5-1732-49bc-8815-d3e45b562352'::uuid, 'mcq', 'The Sun looks reddish at sunrise and sunset because', array['light travels a longer path through air, so most blue light is scattered away and mostly red reaches us', 'red light is scattered the most, towards us', 'the Sun is cooler in the morning and evening', 'the ocean reflects red light upwards']::text[], '[0]'::jsonb, 'Near the horizon sunlight passes through much more air; blue is scattered out along the way, leaving mainly the longer red wavelengths.', 'medium', 1, false, true, array['', 'Red light is scattered the most', '', 'Sky is blue because it reflects the sea']::text[]),
    ('f1be4ea9-1744-4941-8f93-6e59d12fcfde'::uuid, 'f0de0ca5-1732-49bc-8815-d3e45b562352'::uuid, 'mcq', 'Danger signal lights are red because red light', array['is scattered the most, so it spreads everywhere', 'is reflected strongly by the sky', 'travels fastest in air', 'is scattered the least by fog and smoke, so it can be seen from far away']::text[], '[3]'::jsonb, 'Red has the longest wavelength in the visible spectrum, so it is scattered least and travels farthest through fog or smoke.', 'hard', 1, false, true, array['Red light is scattered the most', 'Sky is blue because it reflects the sea', '', '']::text[]),
    ('29bd2c12-f686-4c12-8517-dd85d63d704e'::uuid, 'fa0bb3bc-16ac-4fbe-8a89-03c04066abd2'::uuid, 'mcq', 'A charge of 60 C flows through a wire in 2 minutes. What is the current?', array['30 A', '120 A', '0.5 A', '2 A']::text[], '[2]'::jsonb, 'I = Q/t = 60 C / 120 s = 0.5 A; time must be in seconds.', 'easy', 1, false, true, array['', '', '', '']::text[]),
    ('0db96333-51ae-49ca-87c9-f1ff5a64b563'::uuid, 'fa0bb3bc-16ac-4fbe-8a89-03c04066abd2'::uuid, 'mcq', 'Two ammeters are placed just before and just after a bulb in a simple circuit. The first reads 0.4 A. What does the second read?', array['Less than 0.4 A, because the bulb used up some current', '0.4 A', '0 A, because the bulb used up all the current', 'More than 0.4 A']::text[], '[1]'::jsonb, 'Charge is not used up in a bulb; the same current flows all the way round a series loop. The bulb converts energy, not charge.', 'medium', 1, false, true, array['Current gets used up by components', '', 'Current gets used up by components', '']::text[]),
    ('c92d2ddb-c033-4d46-8273-b5efedcaba04'::uuid, 'fa0bb3bc-16ac-4fbe-8a89-03c04066abd2'::uuid, 'mcq', 'In a metal wire connected to a cell, which way do the electrons drift?', array['From the + terminal to the − terminal, the same way as conventional current', 'They only vibrate, with no net movement', 'From + to −, while conventional current goes from − to +', 'From the − terminal to the + terminal, opposite to conventional current']::text[], '[3]'::jsonb, 'Conventional current was defined as flowing from + to −; electrons are negative, so they drift from − to +.', 'hard', 1, false, true, array['Electrons move in the conventional current direction', '', '', '']::text[]),
    ('b880fcf6-9d8f-4c5d-8cf3-03391dafa270'::uuid, '1c2b9f29-b68a-49fa-823a-825cb7ef77bd'::uuid, 'mcq', 'How should a voltmeter be connected to measure the potential difference across a resistor?', array['In parallel across the resistor', 'In series with the resistor', 'In series between the battery and the switch', 'Anywhere in the circuit; it does not matter']::text[], '[0]'::jsonb, 'A voltmeter compares two points, so it is connected in parallel across the component.', 'easy', 1, false, true, array['', 'Voltmeter is connected in series', 'Voltmeter is connected in series', '']::text[]),
    ('0e26472d-1d73-4655-8d35-0755bcfe4c73'::uuid, '1c2b9f29-b68a-49fa-823a-825cb7ef77bd'::uuid, 'mcq', '12 J of work is done in moving 3 C of charge between two points. What is the potential difference between them?', array['36 V', '0.25 V', '4 V', '4 A, because the charge flows between the points']::text[], '[2]'::jsonb, 'V = W/Q = 12 J / 3 C = 4 V.', 'medium', 1, false, true, array['', '', '', 'Voltage flows through the circuit']::text[]),
    ('bf704d8a-1df2-478f-8a52-8fc74d9845db'::uuid, '1c2b9f29-b68a-49fa-823a-825cb7ef77bd'::uuid, 'mcq', 'Which statement about potential difference is correct?', array['It is the amount of charge flowing past a point each second', 'It is the work done per unit charge in moving charge between two points', 'It flows through a resistor and is used up there', 'A voltmeter must have very low resistance']::text[], '[1]'::jsonb, 'V = W/Q: potential difference is energy per unit charge between two points; charge per second is current.', 'hard', 1, false, true, array['Voltage flows through the circuit', '', 'Voltage flows through the circuit', '']::text[]),
    ('edf67eb8-a7eb-431b-8693-5037ea7581ce'::uuid, 'dd3df846-b4b5-4a1e-8fdb-45cf621d27dc'::uuid, 'mcq', 'A copper wire lying on a table is not connected to any cell. Does a current flow in it?', array['Yes, a large current, because copper has many free electrons', 'Yes, a small current that slowly runs out', 'No net current, because there is no potential difference across it', 'Only when the wire is heated']::text[], '[2]'::jsonb, 'Free electrons move randomly, but a net flow of charge needs a potential difference across the conductor.', 'easy', 1, false, true, array['Current flows without a potential difference', 'Current flows without a potential difference', '', '']::text[]),
    ('57f4bac0-8d13-498d-8567-afbab828b3f4'::uuid, 'dd3df846-b4b5-4a1e-8fdb-45cf621d27dc'::uuid, 'mcq', 'The potential difference across an ohmic resistor is doubled at constant temperature. What happens?', array['The resistance doubles and the current stays the same', 'Both the current and the resistance double', 'The current doubles and the resistance stays the same', 'The current halves']::text[], '[2]'::jsonb, 'By Ohm''s law I = V/R; R is fixed for the conductor, so doubling V doubles I.', 'medium', 1, false, true, array['Resistance rises when voltage rises', 'Resistance rises when voltage rises', '', '']::text[]),
    ('677c607c-c065-4907-8428-16acf59cfda5'::uuid, 'dd3df846-b4b5-4a1e-8fdb-45cf621d27dc'::uuid, 'mcq', 'A 5 Ω resistor carries 0.4 A. What potential difference is needed to double the current?', array['4 V', '2 V, because doubling the current halves the resistance', '1 V', '8 V']::text[], '[0]'::jsonb, 'Now V = IR = 0.4 × 5 = 2 V; for 0.8 A through the same 5 Ω, V = 0.8 × 5 = 4 V.', 'hard', 1, false, true, array['', 'Resistance rises when voltage rises', '', '']::text[]),
    ('5e83186b-b594-404d-82f8-3de6f40b50b0'::uuid, 'a5a93904-9679-4f33-8c4c-4bdc46a19bc0'::uuid, 'mcq', 'Four wires are made of the same metal. Which one has the least resistance?', array['Long and thin', 'Short and thick', 'Long and thick', 'Short and thin']::text[], '[1]'::jsonb, 'R = ρl/A: resistance falls with shorter length and with larger cross-sectional area.', 'easy', 1, false, true, array['', '', '', 'Thicker wires have more resistance']::text[]),
    ('22dfed0c-ddec-460b-86f4-abb9c2a99a37'::uuid, 'a5a93904-9679-4f33-8c4c-4bdc46a19bc0'::uuid, 'mcq', 'A wire is cut into two equal halves. What is the resistivity of each half?', array['The same as the original wire', 'Half of the original', 'Double the original', 'One-fourth of the original']::text[], '[0]'::jsonb, 'Resistivity is a property of the material, so it does not change; each half has half the resistance, not half the resistivity.', 'medium', 1, false, true, array['', 'Confuses resistivity with resistance', 'Confuses resistivity with resistance', '']::text[]),
    ('59a576c7-3d0d-44a2-8e07-300875cbbea8'::uuid, 'a5a93904-9679-4f33-8c4c-4bdc46a19bc0'::uuid, 'mcq', 'A wire of resistance R is stretched to twice its length while its volume stays the same. What is its new resistance?', array['2R', 'R, because the material is the same', '4R', 'R/2, because the wire becomes thinner']::text[], '[2]'::jsonb, 'Doubling l halves A (same volume), so R = ρl/A becomes ρ(2l)/(A/2) = 4R.', 'hard', 1, false, true, array['', 'Confuses resistivity with resistance', '', 'Thicker wires have more resistance']::text[]),
    ('52f249a8-2007-4451-87ca-cf5d489925c4'::uuid, '3bb42e56-9e47-449b-8878-b44affcdf81c'::uuid, 'mcq', 'Resistors of 2 Ω, 3 Ω and 5 Ω are connected in series. What is the equivalent resistance?', array['30 Ω', '0.97 Ω', '10 Ω', '5 Ω']::text[], '[2]'::jsonb, 'In series, Rs = R1 + R2 + R3 = 2 + 3 + 5 = 10 Ω.', 'easy', 1, false, true, array['', '', '', '']::text[]),
    ('1f363bb6-9fdc-4436-83c4-ca9c632688f7'::uuid, '3bb42e56-9e47-449b-8878-b44affcdf81c'::uuid, 'mcq', 'Two identical bulbs are connected in series with a battery. How does the bulb farther from the battery compare with the nearer one?', array['Dimmer, because the first bulb gets the current first', 'Equally bright, because the same current flows through both', 'Brighter, because current speeds up', 'Off, because current divides and none is left']::text[], '[1]'::jsonb, 'In series the same current flows through every component, so identical bulbs glow equally.', 'medium', 1, false, true, array['First bulb in series is brightest', '', '', 'Current differs across series components']::text[]),
    ('acae43be-f816-4290-8530-e7ad8fed2029'::uuid, '3bb42e56-9e47-449b-8878-b44affcdf81c'::uuid, 'mcq', 'A 4 Ω and a 2 Ω resistor are connected in series to a 12 V battery. What is the potential difference across the 4 Ω resistor?', array['12 V, because each series resistor gets the full battery voltage', '4 V', '6 V', '8 V']::text[], '[3]'::jsonb, 'I = 12 V / 6 Ω = 2 A, so the p.d. across the 4 Ω resistor is 2 A × 4 Ω = 8 V.', 'hard', 1, false, true, array['Each series component gets the full voltage', '', '', '']::text[]),
    ('b28ac269-650b-4292-8975-4380c3952d5a'::uuid, '2b9c8a71-8371-4ef1-8998-4d12854108ee'::uuid, 'mcq', 'Two 10 Ω resistors are connected in parallel. What is the equivalent resistance?', array['20 Ω', '5 Ω', '10 Ω', '100 Ω']::text[], '[1]'::jsonb, '1/Rp = 1/10 + 1/10 = 2/10, so Rp = 5 Ω, less than either resistor.', 'easy', 1, false, true, array['Adding parallel resistors increases resistance', '', '', '']::text[]),
    ('b10c49e6-b453-49d3-87a0-3f7385c2943a'::uuid, '2b9c8a71-8371-4ef1-8998-4d12854108ee'::uuid, 'mcq', 'A 2 Ω and an 8 Ω resistor are connected in parallel across a 4 V battery. What current flows through the 2 Ω resistor?', array['0.5 A', '2 A', '1.25 A, the same as in the 8 Ω branch', '0.4 A']::text[], '[1]'::jsonb, 'Each branch gets the full 4 V, so I = V/R = 4/2 = 2 A through the 2 Ω resistor (and 0.5 A through the 8 Ω).', 'medium', 1, false, true, array['', '', 'Parallel branches get equal current', '']::text[]),
    ('83f510d4-5955-40f6-8ccf-1c0d0e3c84f3'::uuid, '2b9c8a71-8371-4ef1-8998-4d12854108ee'::uuid, 'mcq', 'Why are household appliances connected in parallel rather than in series?', array['Parallel connection increases the total resistance and saves electricity', 'The same current then flows through every appliance', 'Each appliance gets the full mains voltage and can be switched on or off independently', 'Series wiring would need more wire']::text[], '[2]'::jsonb, 'In parallel every appliance gets the full voltage, draws the current it needs, and works independently of the others.', 'hard', 1, false, true, array['Adding parallel resistors increases resistance', 'Parallel branches get equal current', '', '']::text[]),
    ('eb4f69d2-0789-422c-8ce4-f41abd669bba'::uuid, '05e5c4b8-4b57-4122-8efb-4ae6560fa624'::uuid, 'mcq', 'If the current through a heater is doubled while its resistance stays the same, the heat produced in the same time becomes', array['2 times', '4 times', 'half', 'unchanged']::text[], '[1]'::jsonb, 'H = I²Rt, so doubling I multiplies the heat by 2² = 4.', 'easy', 1, false, true, array['Heat is proportional to current, not current²', '', '', '']::text[]),
    ('de06817c-4d9f-400d-8dec-1467419f33db'::uuid, '05e5c4b8-4b57-4122-8efb-4ae6560fa624'::uuid, 'mcq', 'A material is chosen for a fuse wire because it has', array['a low melting point, so it melts when too much current flows', 'a high melting point, so it never melts', 'zero resistance', 'a high melting point and very low resistance']::text[], '[0]'::jsonb, 'A fuse must melt quickly when excess current heats it, breaking the circuit, so it needs a low melting point.', 'medium', 1, false, true, array['', 'Fuse wire needs a high melting point', '', 'Fuse wire needs a high melting point']::text[]),
    ('8f91851d-659c-4af3-8d50-fe7d815e5407'::uuid, '05e5c4b8-4b57-4122-8efb-4ae6560fa624'::uuid, 'mcq', 'A current of 2 A flows through a 5 Ω resistor for 10 s. How much heat is produced?', array['100 J', '20 J', '1000 J', '200 J']::text[], '[3]'::jsonb, 'H = I²Rt = 2² × 5 × 10 = 200 J.', 'hard', 1, false, true, array['Heat is proportional to current, not current²', '', '', '']::text[]),
    ('cfe47243-9ba2-44b4-8749-5d5f805ea814'::uuid, '0b6bb3a5-577d-426f-8e4b-a3a09dd05b59'::uuid, 'mcq', 'One kilowatt-hour (kWh) is a unit of', array['power', 'energy', 'current', 'charge']::text[], '[1]'::jsonb, 'kWh is power × time, so it measures energy; 1 kWh = 3.6 × 10⁶ J.', 'easy', 1, false, true, array['Kilowatt-hour is a unit of power', '', '', '']::text[]),
    ('592dced7-4d6b-436b-8d7c-f2843b2a7f39'::uuid, '0b6bb3a5-577d-426f-8e4b-a3a09dd05b59'::uuid, 'mcq', 'Two bulbs are rated 100 W, 220 V and 60 W, 220 V. Which one has the higher resistance?', array['The 100 W bulb, because it is brighter', 'Both are equal, since they run on the same voltage', 'The 60 W bulb', 'It cannot be decided']::text[], '[2]'::jsonb, 'R = V²/P, so at the same voltage the lower-power 60 W bulb has the higher resistance.', 'medium', 1, false, true, array['Higher wattage bulb has higher resistance', '', '', '']::text[]),
    ('41f375aa-911c-46b3-8f40-41123bb12658'::uuid, '0b6bb3a5-577d-426f-8e4b-a3a09dd05b59'::uuid, 'mcq', 'A 1000 W heater is used for 2 hours a day for 30 days. How much energy does it use?', array['60 kWh', '60,000 kWh', '2 kWh', '60 kW']::text[], '[0]'::jsonb, 'Energy = P × t = 1 kW × (2 h × 30) = 60 kWh.', 'hard', 1, false, true, array['', '', '', 'Kilowatt-hour is a unit of power']::text[]),
    ('e8c0f160-32d0-4f92-809c-bf185454600f'::uuid, '3b10b271-dca9-4fb8-89e7-3fb9e60c532a'::uuid, 'mcq', 'Outside a bar magnet, magnetic field lines run from', array['the north pole to the south pole', 'the south pole to the north pole', 'the middle of the magnet to its ends', 'nowhere; the field exists only on the drawn lines']::text[], '[0]'::jsonb, 'By convention, outside a magnet the field lines emerge from the north pole and enter the south pole.', 'easy', 1, false, true, array['', '', '', 'Field lines are physical things']::text[]),
    ('7aa6c9b8-2cc6-40a5-879d-ea99f7618237'::uuid, '3b10b271-dca9-4fb8-89e7-3fb9e60c532a'::uuid, 'mcq', 'Why do two magnetic field lines never intersect?', array['They do intersect near strong magnets', 'At an intersection a compass would point in two directions at once, which is impossible', 'They are physical strands that would collide', 'The field is zero between the lines']::text[], '[1]'::jsonb, 'The tangent to a field line gives the field direction; a crossing would give two directions at one point.', 'medium', 1, false, true, array['Magnetic field lines can cross', '', 'Field lines are physical things', 'Field lines are physical things']::text[]),
    ('8c374e00-7af4-43d1-8c8f-15abb4373727'::uuid, '3b10b271-dca9-4fb8-89e7-3fb9e60c532a'::uuid, 'mcq', 'Where is the magnetic field of a bar magnet strongest?', array['Where the field lines are farthest apart', 'Where the field lines cross each other', 'Where the field lines are closest together, near the poles', 'At the middle of the magnet, between the lines']::text[], '[2]'::jsonb, 'The closeness of field lines shows field strength, and they crowd together near the poles.', 'hard', 1, false, true, array['', 'Magnetic field lines can cross', '', 'Field lines are physical things']::text[]),
    ('80d72bba-3c7b-4ad9-89b1-043f0d2aafd8'::uuid, '180afbe2-8f1d-4624-891d-95c3cebe2d52'::uuid, 'mcq', 'The magnetic field lines around a straight current-carrying wire are', array['straight lines parallel to the wire', 'concentric circles around the wire', 'straight lines pointing out from the wire', 'absent; a wire has no field']::text[], '[1]'::jsonb, 'A straight current produces circular field lines centred on the wire, in planes perpendicular to it.', 'easy', 1, false, true, array['Field runs along the wire', '', '', '']::text[]),
    ('d0085f80-340c-4135-870e-1601717cec6e'::uuid, '180afbe2-8f1d-4624-891d-95c3cebe2d52'::uuid, 'mcq', 'Current flows vertically upwards in a straight wire. Seen from above, in which direction do the field lines run?', array['Clockwise', 'Upwards along the wire', 'Anticlockwise', 'There are no field lines, because the wire is not a magnet']::text[], '[2]'::jsonb, 'By the right-hand thumb rule, with the thumb pointing up towards the viewer, the fingers curl anticlockwise.', 'medium', 1, false, true, array['', 'Field runs along the wire', '', '']::text[]),
    ('a816447c-6451-4b94-8adb-2b9475afb3de'::uuid, '180afbe2-8f1d-4624-891d-95c3cebe2d52'::uuid, 'mcq', 'A compass near a straight wire deflects to the east when current flows. The current is then reversed. What does the needle do?', array['It deflects to the west', 'It keeps deflecting east, because the wire is now magnetised', 'It points along the wire', 'It stays still because only the current''s size matters']::text[], '[0]'::jsonb, 'Reversing the current reverses the circular field around the wire, so the needle deflects the opposite way.', 'hard', 1, false, true, array['', 'Wire stays magnetic without current', 'Field runs along the wire', '']::text[]),
    ('59df27a0-0d32-4164-8443-7a61d21135fa'::uuid, '9246dada-ee7e-4102-802c-eaa5c07ddae3'::uuid, 'mcq', 'The magnetic field inside a long current-carrying solenoid is', array['zero', 'uniform, with parallel straight field lines', 'strongest near the coils and zero at the centre', 'circular around the axis']::text[], '[1]'::jsonb, 'Inside a long solenoid the field lines are parallel straight lines, so the field is the same at all points.', 'easy', 1, false, true, array['Solenoid field is only outside the coils', '', 'Solenoid field is only outside the coils', '']::text[]),
    ('82e82fd1-c814-4f98-8770-3eb0cc3857c7'::uuid, '9246dada-ee7e-4102-802c-eaa5c07ddae3'::uuid, 'mcq', 'A solenoid with a soft-iron core is used as an electromagnet. When the current is switched off, the core', array['loses almost all of its magnetism', 'remains a strong permanent magnet', 'swaps its north and south poles', 'becomes a stronger magnet']::text[], '[0]'::jsonb, 'Soft iron is magnetised only while the current flows, which is why electromagnets can be switched on and off.', 'medium', 1, false, true, array['', 'An electromagnet stays magnetised when switched off', '', '']::text[]),
    ('f2401e60-0d3e-47e6-8be2-7ae219da9898'::uuid, '9246dada-ee7e-4102-802c-eaa5c07ddae3'::uuid, 'mcq', 'One end of a current-carrying solenoid behaves like a north pole. If the current is reversed, that end', array['stays a north pole, because the iron keeps its poles', 'has no pole, since the field exists only outside the coils', 'becomes a south pole', 'becomes neutral but still attracts iron']::text[], '[2]'::jsonb, 'The polarity of a solenoid depends on the direction of the current, so reversing the current swaps the poles.', 'hard', 1, false, true, array['An electromagnet stays magnetised when switched off', 'Solenoid field is only outside the coils', '', '']::text[]),
    ('03b0bda2-ed58-4241-8edf-8d12b3bf13a1'::uuid, '3bb5b5c9-4627-4a6c-8c93-93ec363a13e1'::uuid, 'mcq', 'The direction of the force on a current-carrying conductor in a magnetic field is given by', array['Fleming''s left-hand rule', 'Fleming''s right-hand rule', 'the right-hand thumb rule', 'Snell''s law']::text[], '[0]'::jsonb, 'Fleming''s left-hand rule: forefinger along the field, middle finger along the current, thumb gives the force.', 'easy', 1, false, true, array['', 'Uses a right-hand rule for the force', 'Uses a right-hand rule for the force', '']::text[]),
    ('d222eaba-ac8f-401b-8d76-dd0437f502b8'::uuid, '3bb5b5c9-4627-4a6c-8c93-93ec363a13e1'::uuid, 'mcq', 'The force on a current-carrying wire in a uniform magnetic field is largest when the wire is', array['parallel to the field', 'perpendicular to the field', 'at 45° to the field', 'at any angle; the force does not depend on angle']::text[], '[1]'::jsonb, 'The force is maximum when current and field are perpendicular, and zero when they are parallel.', 'medium', 1, false, true, array['Force is largest when current is parallel to field', '', '', '']::text[]),
    ('48dbf225-6a54-492d-8d2e-4bc347f5a2a0'::uuid, '3bb5b5c9-4627-4a6c-8c93-93ec363a13e1'::uuid, 'mcq', 'A horizontal wire carries current towards the east in a horizontal magnetic field pointing north. Which way is the force on the wire?', array['Vertically downwards', 'Vertically upwards', 'Towards the north', 'There is no force, since the field and current are horizontal']::text[], '[1]'::jsonb, 'By Fleming''s left-hand rule (field north, current east), the thumb points vertically upwards.', 'hard', 1, false, true, array['Uses a right-hand rule for the force', '', '', 'Force is largest when current is parallel to field']::text[]),
    ('4ef8a9a1-5e87-442c-8e37-bd9b7f730cc5'::uuid, '0f4d2cae-cf64-4062-8b65-f1dffd3bb2d3'::uuid, 'mcq', 'In a household circuit, the fuse is connected in', array['the live wire', 'the neutral wire', 'the earth wire', 'any wire; it does not matter']::text[], '[0]'::jsonb, 'The fuse goes in the live wire so that when it melts, the appliance is disconnected from the high-potential supply.', 'easy', 1, false, true, array['', 'Fuse can go in the neutral wire', 'Earth wire carries current in normal use', 'Fuse can go in the neutral wire']::text[]),
    ('6ca49128-eaea-41b4-8324-b19fdbcaca07'::uuid, '0f4d2cae-cf64-4062-8b65-f1dffd3bb2d3'::uuid, 'mcq', 'What is the job of the earth wire on a metal-bodied appliance?', array['It carries current back to the mains during normal use', 'It provides a low-resistance path to the ground if the body becomes live, protecting the user', 'It increases the voltage supplied to the appliance', 'The appliance needs it to work at all']::text[], '[1]'::jsonb, 'The earth wire normally carries no current; in a fault it lets current flow safely to the ground so the user is not shocked.', 'medium', 1, false, true, array['Earth wire carries current in normal use', '', '', 'Earth wire carries current in normal use']::text[]),
    ('0e75b5fa-897f-409c-871a-db2b29019443'::uuid, '0f4d2cae-cf64-4062-8b65-f1dffd3bb2d3'::uuid, 'mcq', 'When the live and neutral wires touch directly (a short circuit), the current', array['drops to zero, because the circuit becomes shorter', 'flows only through the earth wire', 'rises sharply, because the resistance becomes very small', 'stays the same']::text[], '[2]'::jsonb, 'With almost no resistance in the path, I = V/R becomes very large, which is why a fuse or MCB is needed.', 'hard', 1, false, true, array['A short circuit reduces the current', 'Earth wire carries current in normal use', '', '']::text[])
on conflict do nothing;

commit;
